        try { m.bottom = data.bottom; } catch (e) {}
        try { m.left = data.left; } catch (e) {}
        try { m.right = data.right; } catch (e) {}
        try { m.columnCount = data.columnCount; } catch (e) {}
        try { m.columnGutter = data.columnGutter; } catch (e) {}
    }

    function getPageById(doc, id) {
        for (var i = 0; i < doc.pages.length; i++) {
            if (doc.pages[i].id === id) {
                return doc.pages[i];
            }
        }

        return null;
    }

    function getPageItemById(doc, id) {
        try {
            return doc.pageItems.itemByID(id);
        } catch (e) {
            return null;
        }
    }

    function isValidPageItem(it) {
        if (!it) {
            return false;
        }

        try {
            if (!it.isValid) {
                return false;
            }
        } catch (e) {
            return false;
        }

        return true;
    }

    function unlockLayers(doc) {
        var states = [];

        for (var i = 0; i < doc.layers.length; i++) {
            var l = doc.layers[i];

            states.push({
                layer: l,
                locked: l.locked,
                visible: l.visible
            });

            try { l.locked = false; } catch (e) {}
            try { l.visible = true; } catch (e) {}
        }

        return states;
    }

    function restoreLayers(states) {
        for (var i = 0; i < states.length; i++) {
            try { states[i].layer.locked = states[i].locked; } catch (e) {}
            try { states[i].layer.visible = states[i].visible; } catch (e) {}
        }
    }

    function unlockItemTree(item) {
        try { item.locked = false; } catch (e) {}

        try {
            if (item.allPageItems && item.allPageItems.length) {
                for (var i = 0; i < item.allPageItems.length; i++) {
                    try { item.allPageItems[i].locked = false; } catch (e) {}
                }
            }
        } catch (e) {}
    }

    function sideSuffix(sideString) {
        sideString = String(sideString).toLowerCase();

        if (sideString.indexOf("left") !== -1) {
            return "LEFT";
        }

        if (sideString.indexOf("right") !== -1) {
            return "RIGHT";
        }

        return "SINGLE";
    }

    function makeUniqueMasterName(doc, baseName) {
        var name = baseName;
        var counter = 1;

        while (masterNameExists(doc, name)) {
            name = baseName + "_" + counter;
            counter++;
        }

        return name;
    }

    function masterNameExists(doc, name) {
        for (var i = 0; i < doc.masterSpreads.length; i++) {
            if (doc.masterSpreads[i].name === name) {
                return true;
            }
        }

        return false;
    }

})();
